const TIME_LIMIT: int = 2200;
const TH18_RING_BALL2: int = 464;
const TH18_RICE: int = 480;

async sub b_shoot(last: int) {
    var rank: int = global(GVAR_RANK);
    var speed: fx = 2.2fx;
    if rank == 2 && last == 0 { speed = 3fx; }
    if rank == 3 { speed = 3.5fx; }
    set_self_fx(0, speed);
    var rounds: int = 1;
    var interval: int = 10;
    if rank == 1 { rounds = 5; }
    if rank == 2 { rounds = 15; }
    if rank == 3 { rounds = 25; interval = 20; }
    if last != 0 {
        rounds = 2; interval = 80;
        if rank == 1 { rounds = 10; }
        if rank == 2 || rank == 3 { rounds = 15; interval = 20; }
    }
    sh_reset(0);
    sh_sprite(0, TH18_RING_BALL2, 4);
    sh_aim(0, 1);
    sh_count(0, 1, 1);
    for i in 0..rounds {
        speed = self_fx(0);
        sh_speed(0, speed, 0fx);
        sh_dist(0, -4fx * speed);
        sh_fire(0);
        wait(interval);
    }
}
async sub girl_b(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx); set_hitbox(8fx);
    var a: angle = 45deg;
    var b: angle = -22.5deg;
    var c: angle = 180deg;
    var d: angle = 22.5deg;
    if mirror != 0 { a = 135deg; b = 202.5deg; c = 0deg; d = 157.5deg; }
    move_vel(0, a, 4fx, EASE_LINEAR);
    var zero: angle = 0deg;
    if mirror != 0 { zero = 180deg; }
    move_vel(50, zero, 0fx, EASE_QUAD_IN);
    wait(60); spawn b_shoot(0);
    wait(110); move_vel(60, b, 3fx, EASE_QUAD_IN);
    wait(60); move_vel(60, b, 0fx, EASE_QUAD_IN);
    wait(60); spawn b_shoot(0);
    wait(60); move_vel(0, c, 0fx, EASE_LINEAR); move_vel(60, c, 3fx, EASE_QUAD_IN);
    wait(60); move_vel(60, c, 0fx, EASE_QUAD_IN);
    wait(60); spawn b_shoot(0);
    wait(60); move_vel(0, d, 0fx, EASE_LINEAR); move_vel(60, d, 2fx, EASE_QUAD_IN); spawn b_shoot(1);
    loop { wait(600); }
}
// st01 GirlD02: source 1111-1185.
async sub d_shoot() {
    wait(60);
    var rank: int = global(GVAR_RANK);
    var speed: fx = 1.6fx; var rounds: int = 3; var interval: int = 140;
    if rank == 1 { rounds = 7; interval = 60; }
    if rank == 2 { speed = 2.6fx; rounds = 13; interval = 30; }
    if rank == 3 { speed = 3.5fx; rounds = 30; interval = 15; }
    sh_reset(0); sh_sprite(0, TH18_RICE, 8);
    sh_ring(0, 1); sh_aim(0, 1); sh_count(0, 12, 1);
    sh_speed(0, speed, 0fx); sh_dist(0, -4fx * speed);
    var a: angle = 0deg;
    for i in 0..rounds {
        sh_angle(0, a, 3deg); sh_fire(0);
        a = a + 40504 as angle;
        wait(interval);
    }
}
async sub girl_d() {
    set_invuln(65535); set_hurtbox(16fx); set_hitbox(12fx);
    move_vel(0, 90deg, 4fx, EASE_LINEAR);
    move_vel(60, 90deg, 0fx, EASE_QUAD_IN);
    spawn d_shoot();
    wait(600); move_vel(120, 90deg, 0.2fx, EASE_QUAD_IN);
    loop { wait(600); }
}
